    [9] = {
      beijing = 4961,
      role1 = 4191000,
      role2 = 403111,
      role3 = 403207,
      role5 = 4191401,
      sentence = "Just a fleeting thought, casual and unspoken. But when such a thought becomes reality, it brings a kind of quiet joy that takes you by surprise.",
      voice = 1,
      role_pos = "-15,-1088,0",
      voice_wait = 1000
    },
    [10] = {
